import math

def is_power_of_two(n):
    """Checks if a positive integer n is a power of two."""
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

solutions = []
N_MAX = 5
X_MAX = 10 # Testing small values for x

for n in range(2, N_MAX + 1):
    # Start x from n + 1
    for x in range(n + 1, X_MAX + 1):
        V = x**n + x - 2

        if is_power_of_two(V):
            # Calculate k such that 2^k = V
            # Since V is a power of 2, k = log2(V)
            k = V.bit_length() - 1
            solutions.append((x, n, k))

print("Solutions found (x, n, k):")
for sol in solutions:
    print(sol)

